// src/physics/physics-debug-renderer.ts
var PhysicsDebugRenderer = class {
  static {
    __name(this, "PhysicsDebugRenderer");
  }
  gpu;
  debugRenderActor = new Actor();
  debugRenderGeometry;
  constructor(gpu) {
    this.gpu = gpu;
    this.debugRenderActor.label = "PhysicsDebugRenderer Proxy";
    this.debugRenderActor.add(new UnlitMaterial(gpu, { depthTest: false }));
  }
  addToStage(stage, actor) {
    stage.attachChild(this.debugRenderActor);
  }
  removeFromStage(stage, actor) {
    stage.removeChild(this.debugRenderActor);
  }
  //static TickOrder = 1;
  onTick(tickData, actor) {
    let stagePhysics = actor.stage?.get(StagePhysics);
    if (!stagePhysics) {
      return;
    }
    const debugBuffers = stagePhysics.world.debugRender();
    this.debugRenderGeometry = new Geometry(this.gpu, {
      label: "PhysicsDebugRenderer Geometry",
      position: debugBuffers.vertices,
      color: debugBuffers.colors,
      topology: "line-list"
    });
    this.debugRenderActor.add(this.debugRenderGeometry);
  }
};

// src/settings-menu.ts
var SettingsMenu = class {
  static {
    __name(this, "SettingsMenu");
  }
  appState;
  pane;
  stats;
  debug;
  constructor(appState) {
    this.appState = appState;
    this.pane = new Pane({
      title: document.title.split("-")[0]
    });
    this.pane.hidden = true;
    this.pane.addButton({
      title: "Save"
    }).on("click", () => {
      const json = this.appState.serializeDecalLayout();
      const blob = new Blob([json], { type: "text/json" });
      const link = document.createElement("a");
      link.download = "decalLayout.json";
      link.href = window.URL.createObjectURL(blob);
      link.dataset.downloadurl = ["text/json", link.download, link.href].join(":");
      link.click();
      link.remove();
    });
    this.pane.addButton({
      title: "Load"
    }).on("click", () => {
      let input = document.createElement("input");
      input.type = "file";
      input.onchange = async () => {
        let file = input.files?.item(0);
        if (file) {
          this.appState.deserializeDecalLayoutFromString(await file.text());
        }
      };
      input.click();
    });
    this.pane.addButton({
      title: "View Source"
    }).on("click", () => {
      window.open("https://github.com/toji/emoji-graffiti", "_blank").focus();
    });
    this.stats = this.pane.addFolder({ title: "Decal Stats", expanded: false });
    this.stats.addBinding(this.appState.gpu, "useBindless", {
      readonly: true,
      label: "Bindless"
    });
    this.stats.addBinding(this.appState.gpu.decalManager, "decalCount", {
      readonly: true,
      label: "Decals",
      format: /* @__PURE__ */ __name((v3) => v3.toFixed(0), "format")
    });
    this.stats.addBinding(this.appState.gpu.decalManager, "decalTextureCount", {
      readonly: true,
      label: "Textures",
      format: /* @__PURE__ */ __name((v3) => v3.toFixed(0), "format")
    });
    this.stats.addBinding(this.appState.gpu.decalManager, "decalMemory", {
      readonly: true,
      label: "Memory",
      format: /* @__PURE__ */ __name((v3) => {
        if (v3 < 1024) {
          return `${v3}b`;
        }
        v3 /= 1024;
        if (v3 < 1024) {
          return `${parseFloat(v3.toFixed(2))}kb`;
        }
        v3 /= 1024;
        if (v3 < 1024) {
          return `${parseFloat(v3.toFixed(2))}mb`;
        }
        v3 /= 1024;
        if (v3 < 1024) {
          return `${parseFloat(v3.toFixed(2))}gb`;
        }
      }, "format")
    });
    if (this.appState.debug) {
      this.debug = this.pane.addFolder({ title: "Debug", expanded: false });
      this.debug.addBinding(this.appState.config, "physicsDebugRendering", {
        label: "Physics Debug"
      }).on("change", (ev) => {
        this.#updatePhysicsDebugRendering();
      });
      this.debug.addBinding(this.appState.config, "flying");
      this.debug.addBinding(this.appState.config, "noclip");
      this.#updatePhysicsDebugRendering();
    }
  }
  set hidden(value) {
    this.pane.hidden = value;
  }
  get hidden() {
    return this.pane.hidden;
  }
  #updatePhysicsDebugRendering() {
    if (this.appState.config.physicsDebugRendering) {
      this.appState.stage.add(new PhysicsDebugRenderer(this.appState.gpu));
    } else {
      this.appState.stage.remove(PhysicsDebugRenderer);
    }
  }
};

